<script setup lang="ts">import type{Resume,ResumeEntry}from'@career-launch/shared';import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{repository}from'../../services/repository';import ResumePreview from'./ResumePreview.vue';import{validateResume}from'./validation';const route=useRoute();const resume=ref<Resume|null>(null);const saveState=ref<'saved'|'saving'|'error'>('saved');const validation=computed(()=>resume.value?validateResume(resume.value):{valid:false,errors:[]});function addEntry(key:'education'|'internships'|'projects'){if(!resume.value)return;resume.value[key].push({id:crypto.randomUUID(),title:'',subtitle:'',startsAt:'',endsAt:'',description:''})}function removeEntry(key:'education'|'internships'|'projects',id:string){if(resume.value)resume.value[key]=resume.value[key].filter(item=>item.id!==id)}function move(key:'education'|'internships'|'projects',index:number,direction:-1|1){if(!resume.value)return;const next=index+direction;if(next<0||next>=resume.value[key].length)return;const list=resume.value[key];const current=list[index];const target=list[next];if(!current||!target)return;list[index]=target;list[next]=current}async function save(){if(!resume.value)return;saveState.value='saving';try{resume.value=await repository.resumes.save(resume.value);saveState.value='saved'}catch{saveState.value='error'}}function print(){window.print()}function split(value:string){return value.split(/[，,]/).map(item=>item.trim()).filter(Boolean)}onMounted(async()=>{resume.value=await repository.resumes.get(String(route.params.id))})</script>
<template><section v-if="resume" class="editor-page"><header class="editor-bar"><div><RouterLink to="/me/resumes">返回简历中心</RouterLink><input v-model="resume.name" aria-label="简历名称"/></div><span :data-state="saveState">{{saveState==='saved'?'已保存':saveState==='saving'?'保存中…':'保存失败'}}</span><label>模板<select v-model="resume.template"><option value="classic">经典专业</option><option value="modern">现代简洁</option></select></label><input v-model="resume.accentColor" aria-label="主题色" type="color"/><button class="cl-quiet-button" @click="save">保存</button><button class="cl-primary-button" @click="print">导出 PDF</button></header><div class="editor-grid"><main class="form-panel"><section class="form-section cl-card"><h2>基本信息</h2><div class="two"><label>姓名<input v-model="resume.profile.name"/></label><label>求职方向<input v-model="resume.profile.targetRole"/></label><label>邮箱<input v-model="resume.profile.email" type="email"/></label><label>手机<input v-model="resume.profile.phone"/></label><label>所在城市<input v-model="resume.profile.city"/></label></div></section><section v-for="group in ([['education','教育经历'],['internships','实习经历'],['projects','项目经历']] as const)" :key="group[0]" class="form-section cl-card"><header><h2>{{group[1]}}</h2><button class="cl-quiet-button" @click="addEntry(group[0])">新增</button></header><div v-for="(item,index) in resume[group[0]]" :key="item.id" class="entry-form"><div class="entry-actions"><button @click="move(group[0],index,-1)">上移</button><button @click="move(group[0],index,1)">下移</button><button @click="removeEntry(group[0],item.id)">删除</button></div><label>学校 / 公司 / 项目名<input v-model="item.title"/></label><label>专业 / 职位 / 角色<input v-model="item.subtitle"/></label><div class="two"><label>开始时间<input v-model="item.startsAt" type="month"/></label><label>结束时间<input v-model="item.endsAt" type="month"/></label></div><label>经历描述<textarea v-model="item.description" rows="4" placeholder="说明你的行动、使用的方法和最终结果"></textarea></label></div></section><section class="form-section cl-card"><h2>技能与亮点</h2><label>个人简介<textarea v-model="resume.summary" rows="4"></textarea></label><label>专业技能<input :value="resume.skills.join('，')" @input="resume.skills=split(($event.target as HTMLInputElement).value)" placeholder="使用逗号分隔"/></label><label>荣誉奖项<input :value="resume.honors.join('，')" @input="resume.honors=split(($event.target as HTMLInputElement).value)" placeholder="使用逗号分隔"/></label></section><p v-if="!validation.valid" class="validation-tip">还有 {{validation.errors.length}} 项基础信息需要完善。</p></main><aside class="preview-panel"><ResumePreview :resume="resume"/></aside></div></section><section v-else class="cl-page cl-container">正在打开简历…</section></template>
<style scoped>.editor-page{min-height:100vh;background:var(--cl-canvas)}.editor-bar{position:sticky;z-index:20;top:68px;display:flex;align-items:center;gap:12px;padding:11px 22px;border-bottom:1px solid var(--cl-border);background:var(--cl-surface)}.editor-bar>div{display:grid;margin-right:auto}.editor-bar a{color:var(--cl-primary);font-size:12px}.editor-bar input[aria-label="简历名称"]{width:220px;border:0;color:var(--cl-text-strong);background:transparent;font-size:18px;font-weight:700}.editor-bar span{color:var(--cl-muted);font-size:12px}.editor-bar label{display:flex;align-items:center;gap:6px}.editor-bar select{height:38px;border:1px solid var(--cl-border);border-radius:7px;background:var(--cl-surface)}.editor-grid{display:grid;grid-template-columns:minmax(430px,580px) minmax(620px,1fr);gap:20px;padding:20px}.form-panel{display:grid;gap:14px}.form-section{padding:20px}.form-section>header{display:flex;justify-content:space-between}.form-section h2{margin:0 0 16px;font-size:18px}.form-section label{display:grid;gap:5px;margin-top:11px;color:var(--cl-muted);font-size:13px;font-weight:700}.form-section input,.form-section textarea{width:100%;padding:9px 10px;border:1px solid var(--cl-border);border-radius:7px;color:var(--cl-text);background:var(--cl-canvas)}.two{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.entry-form{position:relative;margin-top:13px;padding:15px;border:1px solid var(--cl-border);border-radius:9px}.entry-actions{display:flex;justify-content:end;gap:8px}.entry-actions button{border:0;color:var(--cl-primary);background:none;font-size:12px}.preview-panel{overflow:auto;padding:22px;background:#dfe4ed}.preview-panel>:deep(.resume-paper){margin:auto}.validation-tip{color:var(--cl-warning)}@media(max-width:1100px){.editor-bar{top:68px;flex-wrap:wrap}.editor-grid{grid-template-columns:1fr}.preview-panel{display:none}}@media(max-width:600px){.editor-grid{padding:12px}.two{grid-template-columns:1fr}.editor-bar{padding:10px 14px}.editor-bar input[aria-label="简历名称"]{width:160px}}@media print{.editor-bar,.form-panel,.site-header{display:none!important}.editor-grid{display:block;padding:0}.preview-panel{display:block;padding:0;background:#fff}.editor-page{background:#fff}}</style>
